INSERT INTO services (
    business_id, category, name, description,
    duration, price, staff_ids, is_active
) VALUES (
             #{businessId}, #{category}, #{name}, #{description},
             #{duration}, #{price}, #{staffIds}, #{isActive}
         )

mapper.select:
SELECT * FROM services
WHERE business_id = #{businessId}
ORDER BY category, name

SELECT * FROM services
WHERE business_id = #{businessId}
  AND category = #{category}
ORDER BY name

SELECT * FROM services
WHERE business_id = #{businessId}

    AND category = #{category}


    AND is_active = #{isActive, typeHandler=org.apache.ibatis.type.BooleanTypeHandler}


    AND (
    staff_ids IS NULL
    OR staff_ids = ''
    OR staff_ids LIKE '%,' || #{staffId} || ',%'
    OR staff_ids LIKE #{staffId} || ',%'
    OR staff_ids LIKE '%,' || #{staffId}
    OR staff_ids = #{staffId}::TEXT
    )

ORDER BY category, name

SELECT EXISTS(
    SELECT 1 FROM services
    WHERE business_id = #{businessId} AND id = #{id}
)
